using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class DelegationTransportTests
{
    static WorldSession New()=>new(DelegationMission.Create());
    static void At(WorldSession s,long at){while(s.Seconds<at){s.SetPaused(false);var before=s.Seconds;s.AdvanceTo(at);Assert.True(s.Seconds>before);}}
    static string Send(WorldSession s){Assert.Equal(ResultCode.Accepted,s.IssueRegional(DelegationMission.Build(s.DiagnosticSnapshot(),"request:retry-target",RegionalAction.Hold),s.Revision).Code);return s.DiagnosticSnapshot().Region!.Commands.Single().Message;}
    static MessageAttempt Latest(WorldSession s,string m)=>MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,m);
    static string FailAndKnow(WorldSession s,string m){var a=Latest(s,m);s.DiagnosticTransport((flow,t)=>MessageFlow.Fail(flow,m));At(s,a.DueAt);var report=s.DiagnosticSnapshot().Messaging.Messages.Single(x=>x.Kind=="delivery-failure"&&x.Body==a.Id);At(s,Latest(s,report.Id).DueAt);Assert.True(MessageFlow.FailureKnown(s.DiagnosticSnapshot().Messaging,a.Id,s.PlayerControl.Value));return a.Id;}
    static CommandResult Retry(WorldSession s,string m,string a,FieldPoint? address=null,EntityId? actor=null,long? revision=null)=>s.RetryDelegation(m,a,actor??s.PlayerControl,address??s.DiagnosticSnapshot().Delegation!.Terms.KnownAddress,revision??s.Revision);
    [Fact] public void UnreceivedFailureCannotEnableRetry(){var s=New();var m=Send(s);var a=Latest(s,m);Assert.Equal(ResultCode.NotAvailable,Retry(s,m,a.Id).Code);s.DiagnosticTransport((flow,t)=>MessageFlow.Fail(flow,m));At(s,a.DueAt);Assert.Equal(ResultCode.NotAvailable,Retry(s,m,a.Id).Code);Assert.Single(s.DiagnosticSnapshot().Messaging.Attempts,x=>x.MessageId==m);}
    [Fact] public void LostFailureReportDoesNotGrantKnowledge(){var s=New();var m=Send(s);var a=Latest(s,m);s.DiagnosticTransport((flow,t)=>MessageFlow.Fail(flow,m));At(s,a.DueAt);var report=s.DiagnosticSnapshot().Messaging.Messages.Single(x=>x.Kind=="delivery-failure");s.DiagnosticTransport((flow,t)=>MessageFlow.Fail(flow,report.Id));At(s,Latest(s,report.Id).DueAt+100);Assert.False(MessageFlow.FailureKnown(s.DiagnosticSnapshot().Messaging,a.Id,s.PlayerControl.Value));Assert.Equal(ResultCode.NotAvailable,Retry(s,m,a.Id).Code);Assert.Single(s.DiagnosticSnapshot().Messaging.Messages,x=>x.Kind=="delivery-failure");}
    [Fact] public void RetryHasRealPathAndUnchangedBusinessPayload(){var s=New();var m=Send(s);var body=s.DiagnosticSnapshot().Messaging.Messages.Single(x=>x.Id==m);var a=FailAndKnow(s,m);Assert.Equal(ResultCode.Accepted,Retry(s,m,a).Code);var w=s.DiagnosticSnapshot();var attempt=Latest(s,m);Assert.Equal(2,attempt.Number);Assert.Equal(body,w.Messaging.Messages.Single(x=>x.Id==m));var d=w.Region!.Deliveries.Single(d=>d.Attempt==attempt.Id);Assert.Equal(s.Seconds,d.Path[0].StartAt);Assert.Equal(d.Address,d.Path[^1].To);At(s,attempt.DueAt);Assert.Single(s.DiagnosticSnapshot().Delegation!.Plans);Assert.Single(s.DiagnosticSnapshot().Delegation!.Arrivals);}
    [Fact] public void RepeatedFailedAttemptDoesNotSpendAnotherCopy(){var s=New();var m=Send(s);var a=FailAndKnow(s,m);Assert.Equal(ResultCode.Accepted,Retry(s,m,a).Code);var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,Retry(s,m,a,revision:0).Code);Assert.Equal(bytes,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.IdPayloadConflict,Retry(s,m,a,new(0,0)).Code);}
    [Fact] public void UnknownAddressAndImpersonationAreRejected(){var s=New();var m=Send(s);var a=FailAndKnow(s,m);Assert.Equal(ResultCode.NotAvailable,Retry(s,m,a,new(0,0)).Code);Assert.Equal(ResultCode.NotAvailable,Retry(s,m,a,actor:ContractFixture.Clerk).Code);Assert.Equal(ResultCode.NotAvailable,Retry(s,"missing",a).Code);}
    [Fact] public void ReceiptPreventsFurtherRetries(){var s=New();var m=Send(s);var a=FailAndKnow(s,m);Assert.Equal(ResultCode.Accepted,Retry(s,m,a).Code);At(s,Latest(s,m).DueAt);Assert.Equal(ResultCode.NotAvailable,Retry(s,m,Latest(s,m).Id).Code);Assert.Single(s.DiagnosticSnapshot().Delegation!.Plans);}
    [Fact] public void ThreeAttemptsRemainTheHardLimit(){var s=New();var m=Send(s);for(int i=1;i<=3;i++){var a=FailAndKnow(s,m);Assert.Equal(i,Latest(s,m).Number);Assert.Equal(i<3?ResultCode.Accepted:ResultCode.NotAvailable,Retry(s,m,a).Code);}Assert.Equal(3,s.DiagnosticSnapshot().Messaging.Attempts.Count(a=>a.MessageId==m));}
    [Fact] public void RetryReturnAddressIsTheSuccessfulDispatchOrigin(){var s=New();var m=Send(s);var old=s.DiagnosticSnapshot().Region!.Deliveries.Single().Origin;var a=FailAndKnow(s,m);Assert.Equal(ResultCode.Accepted,s.HandleSupply(new("request:pack"),s.PlayerControl,true,FieldSupply.Capacity,s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);Assert.Equal(ResultCode.Accepted,Retry(s,m,a).Code);var attempt=Latest(s,m);var origin=s.DiagnosticSnapshot().Region!.Deliveries.Single(d=>d.Attempt==attempt.Id).Origin;Assert.NotEqual(old,origin);At(s,attempt.DueAt);var w=s.DiagnosticSnapshot();var reply=w.Messaging.Messages.Single(x=>x.Kind=="region-report");Assert.Equal(origin,w.Region!.Deliveries.Single(d=>w.Messaging.Attempts.Single(a=>a.Id==d.Attempt).MessageId==reply.Id).Address);Assert.Equal(origin,w.Region.Deliveries.Single(d=>w.Messaging.Attempts.Single(a=>a.Id==d.Attempt).MessageId==w.Delegation!.Arrivals.Single().Message).Address);}
    [Fact] public void StaleRevisionCannotSend(){var s=New();var m=Send(s);var a=FailAndKnow(s,m);Assert.Equal(ResultCode.StateChanged,Retry(s,m,a,revision:0).Code);Assert.Equal(1,Latest(s,m).Number);}
    [Fact] public void AdapterDoesNotExpandOldProfileAuthority(){var s=new WorldSession(FieldPresence.Create());Assert.Equal(ResultCode.NotAvailable,s.RetryDelegation("missing","missing",s.PlayerControl,new(0,0),s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(20)][InlineData(50)][InlineData(100)]
    public void IntermediateSaveRestoresRetryAndContinue(int delta){var s=New();var m=Send(s);var a=FailAndKnow(s,m);Assert.Equal(ResultCode.Accepted,Retry(s,m,a).Code);At(s,s.Seconds+delta);s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"delegation-retry-"+Guid.NewGuid().ToString("N")),s.DiagnosticSnapshot().Definitions);store.Save(s,"case",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));At(s,s.Seconds+200);At(host.Current,s.Seconds);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Single(s.DiagnosticSnapshot().Delegation!.Plans);}
}
